function cloud(x,y,z,s=1){const g=group(x,y,z);[[-.9,0,0,.7],[0,.15,0,1],[1,0,0,.65]].forEach(a=>ball(a[3],0xfaf9ea,a[0],a[1],a[2],g));g.scale.set(s,s*.6,s*.7);clouds.push(g)}
function clearWorld(){scene.remove(root);root.traverse(o=>{if(o.geometry)o.geometry.dispose()});root=new THREE.Group();scene.add(root);clouds=[];flames=[];smokes=[];character=null;night=false;document.body.classList.remove('night');scene.background.set(0xe7eddb);scene.fog.color.set(0xe7eddb);ambient.intensity=2.5;sun.intensity=3.5;}
function miniFire(x,z,p=root){const g=group(x,0,z,p);for(let i=0;i<3;i++){const l=cyl(.07,.07,.7,0x8c6549,0,.1,0,g,6);l.rotation.z=Math.PI/2;l.rotation.y=i*Math.PI/3}cone(.3,.7,0xea9250,0,.4,0,g,6);cone(.15,.45,0xffd080,0,.5,.1,g,5);return g}
function miniMeal(x,z,p=root){const g=group(x,0,z,p);box(.9,.09,.6,0xc49b68,0,.5,0,g);for(const dx of [-.3,.3])box(.08,.5,.08,0x8c7354,dx,.25,0,g);cyl(.22,.22,.04,0xffe5a3,0,.57,0,g);ball(.12,0xdb9e63,0,.65,0,g);return g}
function japanLand(){for(const rings of japanIslands){const sh=new THREE.Shape();rings[0].forEach(([lon,lat],i)=>{const [x,z]=geoPoint(lon,lat);i?sh.lineTo(x,-z):sh.moveTo(x,-z)});sh.closePath();const side=mesh(new THREE.ExtrudeGeometry(sh,{depth:.85,bevelEnabled:false}),0xb8ab85,0,-.85,0);side.rotation.x=-Math.PI/2;side.userData.layer=-4;const top=mesh(new THREE.ShapeGeometry(sh),0xb5c997,0,.012,0);top.rotation.x=-Math.PI/2;top.userData.layer=-3}}
function setMapView(overview=false){japanOverview=overview;$('#selection').hidden=overview;$('#mapPins').classList.toggle('overview',overview);$('#japanView').classList.toggle('selected',overview);$('#areaView').classList.toggle('selected',!overview);yaw=0;pitch=1.13;if(overview){wantedDist=395;camTarget.set(-28,0,-22);$('#mapCaption').textContent='日本全体 ・ エリアのピンをタップして、旅の続きを'}else{const list=camps.filter(c=>area==='すべて'||c.pref===area);const x=list.reduce((n,c)=>n+c.pin[0],0)/list.length,z=list.reduce((n,c)=>n+c.pin[2],0)/list.length;wantedDist=area==='すべて'?(innerWidth<600?112:91):(innerWidth<600?64:49);camTarget.set(x-(innerWidth<600?1:6),0,z+2);$('#mapCaption').textContent=area==='すべて'?'関東・甲信越・静岡の21キャンプ場':area+'の小さなキャンプ旅'}lastPinLayout=0}
function makeMap(){clearWorld();scene.background.set(0xdce9e5);scene.fog.color.copy(scene.background);scene.fog.near=280;scene.fog.far=800;japanLand();const [fx,fz]=geoPoint(138.73,35.36);fuji(fx,fz,.44);for(const [lon,lat] of [[137.8,36],[137.8,36.6],[138.2,36.9],[139.2,37.2],[140.6,38.4],[140.8,39.1],[135.8,35.2]]){const [x,z]=geoPoint(lon,lat);cone(1.4,2.2,0x92ad82,x,1.1,z,root,6)}for(const c of camps){const [x,,z]=c.pin;const patch=cyl(1.22,1.35,.18,c.color,x,.04,z,root,10);patch.userData.layer=-2;tree(x-1,z-.6,.35,c.land==='forest'?0:1);if(did(c,'tent'))shelter(x-.35,z,.5,root,latestShelter(c));if(did(c,'fire'))miniFire(x+.65,z+.1);if(did(c,'meal'))miniMeal(x+.1,z+.7);if(did(c,'sleep'))box(.6,.12,.35,0x799c91,x-.6,.2,z+.8);if(['river','genshi','highlake'].includes(c.land)){const water=cyl(.6,.65,.03,0x94c4be,x+.8,.15,z-.4,root,12);water.scale.z=.5}}for(const [name,lon,lat] of [['北海道',142.8,43.8],['本州',136.5,35.4],['四国',133.5,33.8],['九州',130.9,32.7]]){const [x,z]=geoPoint(lon,lat),t=textSprite(name,'#718970',1.6);t.position.set(x,.5,z)}$('#mapPins').innerHTML=camps.map((c,i)=>`<button aria-label="${c.name} ${visits(c).length}回訪問" class="pin ${selected===i?'selected':''}" data-pin="${i}"><b>${count(c)>0?'✓':String(i+1).padStart(2,'0')}</b><span class="pinName">${c.short}</span><span class="pinActivities">${actions.filter(a=>did(c,a[0])).map(a=>a[1]).join('')}</span>${visits(c).length?`<em>${visits(c).length}回</em>`:''}</button>`).join('')+`<button id="focusCluster" class="clusterPin">⛺ 21のキャンプ場へ <span>→</span></button>`;document.querySelectorAll('[data-pin]').forEach(b=>b.onclick=()=>selectCamp(+b.dataset.pin));$('#focusCluster').onclick=()=>setMapView(false);updateMap();setMapView(japanOverview);dist=wantedDist;camera.position.set(camTarget.x,Math.sin(pitch)*dist,camTarget.z+Math.cos(pitch)*dist);camera.lookAt(camTarget);camera.updateMatrixWorld()}
function layoutPins(){const now=performance.now();if(now-lastPinLayout<90)return;lastPinLayout=now;camera.updateMatrixWorld();const main=$('#mapUI').getBoundingClientRect(),intro=$('.intro').getBoundingClientRect(),card=$('#selection').getBoundingClientRect();if(japanOverview){const [gx,gz]=geoPoint(139.2,36.3);const v=new THREE.Vector3(gx,.4,gz).project(camera);const cluster=$('#focusCluster');cluster.style.left=Math.max(80,Math.min(innerWidth-180,(v.x*.5+.5)*innerWidth))+'px';cluster.style.top=Math.max(50,Math.min(main.height-60,(-v.y*.5+.5)*innerHeight-main.top))+'px';$('#pinLines').innerHTML='';return}const isMobile=innerWidth<=600;const entries=[];camps.forEach((c,i)=>{const el=document.querySelector(`[data-pin="${i}"]`);if(el.hidden)return;const v=new THREE.Vector3(c.pin[0],1.4,c.pin[2]).project(camera);const ax=(v.x*.5+.5)*innerWidth,ay=(-v.y*.5+.5)*innerHeight-main.top;const w=el.offsetWidth||36,h=el.offsetHeight||32;entries.push({el,ax,ay,x:ax,y:ay,w,h,visible:v.z<1&&v.z>-1})});const left=isMobile?12:Math.min(intro.right+16,innerWidth*.39),right=innerWidth-16,top=14,bottom=main.height-65;for(let pass=0;pass<12;pass++){for(const p of entries){p.x=Math.max(left+p.w/2,Math.min(right-p.w/2,p.x));p.y=Math.max(top+p.h,Math.min(bottom,p.y));const o={left:card.left-8,right:card.right+8,top:card.top-main.top-8,bottom:card.bottom-main.top+8};if(p.x+p.w/2>o.left&&p.x-p.w/2<o.right&&p.y>o.top&&p.y-p.h<o.bottom){if(isMobile)p.y=o.top-5;else p.x=o.left-p.w/2-7}}for(let i=0;i<entries.length;i++)for(let j=i+1;j<entries.length;j++){const a=entries[i],b=entries[j],dx=b.x-a.x,dy=(b.y-b.h/2)-(a.y-a.h/2),ox=(a.w+b.w)/2+7-Math.abs(dx),oy=(a.h+b.h)/2+8-Math.abs(dy);if(ox>0&&oy>0){if(ox<oy){const d=(dx>=0?1:-1)*ox/2;a.x-=d;b.x+=d}else{const d=(dy>=0?1:-1)*oy/2;a.y-=d;b.y+=d}}}}let lines='';for(const p of entries){p.el.style.left=p.x+'px';p.el.style.top=p.y+'px';p.el.style.visibility=p.visible?'visible':'hidden';if(p.visible&&Math.hypot(p.x-p.ax,p.y-p.ay)>14)lines+=`<path d="M${p.ax.toFixed(1)},${p.ay.toFixed(1)} L${p.x.toFixed(1)},${p.y.toFixed(1)}"/>`}$('#pinLines').innerHTML=lines}
function updateMap(){const c=camps[selected];$('#areaFilters').innerHTML=prefectures.map(a=>`<button class="${area===a?'selected':''}" data-area="${a}" aria-pressed="${area===a}">${a}</button>`).join('');document.querySelectorAll('[data-area]').forEach(b=>b.onclick=()=>{area=b.dataset.area;const match=camps.findIndex(c=>area==='すべて'||c.pref===area);if(area!=='すべて'&&camps[selected].pref!==area)selected=match;updateMap();setMapView(false)});$('#campList').innerHTML=camps.map((v,i)=>{if(area!=='すべて'&&v.pref!==area)return '';return `<button class="campRow ${i===selected?'selected':''}" data-camp="${i}"><span class="number">${String(i+1).padStart(2,'0')}</span><span class="campTitle">${v.short}<small>${v.region} ${visits(v).length?'・'+visits(v).length+'回訪問':''}</small><span class="rowBadges">${badges(v)}</span></span><span class="check">${count(v)>0?'✓':'—'}</span></button>`}).join('');document.querySelectorAll('[data-camp]').forEach(b=>b.onclick=()=>selectCamp(+b.dataset.camp));$('#selection').innerHTML=`<div class="eyebrow">${c.pref} / ${c.en}</div><h2>${c.name}</h2><p>${c.desc}</p><div class="tags">${c.tags.map(t=>`<span>${t}</span>`).join('')}</div><div class="stepDots">${count(c)>0?'✓ クリア ・ '+visits(c).length+'回訪問':'まだ訪れていない場所'}</div><div class="selectionBadges">${badges(c)}<span>体験 ${count(c)} / 4</span></div><button class="primary" id="enterCamp"><span>${count(c)?'もう一度あそびに行く':'ここでキャンプする'}</span><span>→</span></button>`;$('#enterCamp').onclick=enterCamp;document.querySelectorAll('.pin').forEach((b,i)=>{b.classList.toggle('selected',selected===i);b.hidden=area!=='すべて'&&camps[i].pref!==area});$('#navCount').textContent=camps.filter(c=>count(c)>0).length+'/'+camps.length;requestAnimationFrame(updateListScroll);lastPinLayout=0}
function selectCamp(i){selected=i;if(area!=='すべて'&&camps[i].pref!==area)area=camps[i].pref;updateMap();if(japanOverview)setMapView(false)}
function shelter(x,z,s=1,p=root,type='dome'){if(type==='ridge')return tent(x,z,s,p);if(type==='cottage')return cabin(x,z,s,p);const g=group(x,0,z,p);if(type==='pole'){cone(1.15,2.2,0xdcb980,0,1.1,0,g,12);rod([0,0,0],[0,2.3,0],.035,0x8c7656,g);const d=new THREE.BufferGeometry();d.setAttribute('position',new THREE.Float32BufferAttribute([-.45,.02,1.07,.45,.02,1.07,0,1.15,.58],3));d.computeVertexNormals();const door=mesh(d,0x526c59,0,0,0,g);door.material=new THREE.MeshStandardMaterial({color:0x526c59,side:THREE.DoubleSide});for(let i=0;i<6;i++){const a=i/6*Math.PI*2;rod([Math.cos(a),.15,Math.sin(a)],[Math.cos(a)*1.5,0,Math.sin(a)*1.5],.014,0xf2e0bb,g)}}else{const dome=mesh(new THREE.SphereGeometry(1.15,16,8,0,Math.PI*2,0,Math.PI/2),0xd99b69,0,.04,0,g);dome.scale.set(1,1,1.12);const door=ball(.55,0x526b59,0,.27,1.08,g,12);door.scale.set(.8,.9,.08);for(const a of [0,Math.PI/2]){const points=[];for(let i=0;i<=24;i++){const q=i/24*Math.PI;points.push(new THREE.Vector3(Math.cos(q)*1.17*Math.cos(a),Math.sin(q)*1.17+.05,Math.cos(q)*1.3*Math.sin(a)))}const curve=new THREE.CatmullRomCurve3(points);mesh(new THREE.TubeGeometry(curve,24,.025,5,false),0xf8dbab,0,0,0,g)}}g.scale.setScalar(s);return g}
function shelterArt(type){const drawings={dome:'<path d="M18 72A42 42 0 0 1 102 72Z" fill="#dea46e"/><path d="M45 72V57a15 15 0 0 1 30 0v15" fill="#55715f"/><path d="M60 30Q35 48 30 72M60 30Q85 48 90 72" fill="none" stroke="#f4d8ad" stroke-width="3"/>',pole:'<path d="M14 74L60 14l46 60Z" fill="#d9be8d"/><path d="M47 74l13-29 13 29Z" fill="#55715f"/><path d="M60 14v-7" stroke="#826c52" stroke-width="3"/>',ridge:'<path d="M14 72L48 20l43 8 22 44Z" fill="#c38b5d"/><path d="M14 72L48 20l36 52Z" fill="#e0a36c"/><path d="M34 72l14-29 16 29Z" fill="#55715f"/>',cottage:'<path d="M23 40h74v35H23Z" fill="#c89f70"/><path d="M12 42L60 13l48 29Z" fill="#5b7565"/><path d="M48 75V48h22v27" fill="#7f7259"/><path d="M29 49h13v13H29ZM78 49h13v13H78Z" fill="#dae4be"/>'};return `<svg viewBox="0 0 120 90" aria-hidden="true">${drawings[type]}<path d="M7 76h106" stroke="#adb990" stroke-width="3" stroke-linecap="round"/></svg>`}
function chooseShelter(){if(busy)return;showModal(`<div class="eyebrow">CHOOSE YOUR LITTLE HOME</div><h2>どんな基地にしよう？</h2><p>好きな形を選んで、設営しよう。今回の訪問の記録にも残ります。</p><div class="shelterGrid">${Object.entries(shelterTypes).map(([id,name])=>`<button data-shelter="${id}">${shelterArt(id)}<strong>${name}</strong><small>これをえらぶ →</small></button>`).join('')}</div><p class="fineprint">ゲーム内の自由な演出です。実際の宿泊施設・利用可能なテントとは異なります。</p>`);document.querySelectorAll('[data-shelter]').forEach(b=>b.onclick=()=>{$('#modal').close();doAction('tent',b.dataset.shelter)})}

function makeBear(){const g=group(.7,0,9.5);g.scale.setScalar(1.25);ball(.35,0xc69b70,0,.55,0,g);const head=ball(.38,0xd7b68e,0,1.05,0,g);for(const a of [-1,1]){ball(.14,0xc69b70,a*.29,1.32,0,g);ball(.075,0xb38d68,a*.29,1.32,.09,g);ball(.11,0xb28d64,a*.2,.12,.08,g);ball(.12,0xd7b68e,a*.4,.6,.02,g);ball(.033,0x34483a,a*.13,1.09,.34,g,8);ball(.07,0xe9bb9e,a*.23,.98,.29,g)}ball(.14,0xf0d5af,0,.95,.34,g);ball(.045,0x44503c,0,1,.46,g);const hat=cyl(.42,.42,.06,0x6b8260,0,1.34,0,g);cyl(.26,.3,.16,0x83996c,0,1.44,0,g);box(.5,.42,.2,0xd28c51,0,.65,-.29,g);box(.52,.08,.22,0xe5b27c,0,.87,-.29,g);return g}
function makeFire(){const g=group(1.4,0,1.4);for(let i=0;i<9;i++)rock(1.4+Math.cos(i/9*Math.PI*2)*.7,1.4+Math.sin(i/9*Math.PI*2)*.7,.17);for(let i=0;i<3;i++){const l=cyl(.1,.13,1.15,0x8c6549,0,.15,0,g,7);l.rotation.z=Math.PI/2;l.rotation.y=i*Math.PI/3}for(let i=0;i<6;i++){const f=cone(.17+Math.random()*.15,.5+Math.random()*.5,i%2?0xffb954:0xec8149,Math.cos(i)*.2,.5,Math.sin(i)*.2,g,7);flames.push(f)}const light=new THREE.PointLight(0xffa34a,5,8);light.position.set(0,1,0);g.add(light);return g}
function makeMeal(){const g=group(-1.4,0,2.4);box(1.5,.12,1,0xc99c6a,0,.7,0,g);for(const x of [-.55,.55])for(const z of [-.32,.32])box(.08,.65,.08,0x876d4f,x,.34,z,g);cyl(.29,.29,.03,0xf8ebcc,0,.79,0,g);ball(.19,0xe4b35f,0,.83,0,g);ball(.08,0x8fa765,.12,.89,0,g);cyl(.11,.09,.2,0x6d8d80,.48,.85,.1,g);box(.8,.09,.65,0xc79c6b,0,.35,1.05,g);for(const x of [-.28,.28])box(.06,.33,.06,0x886c4b,x,.17,1.05,g);return g}
function makeCamp(){clearWorld();scene.fog.near=65;scene.fog.far=140;const c=camps[selected];const land=cyl(12,12.3,1.3,c.color,0,-.7,0,root,12);cyl(12.3,11.6,.35,0xb7aa86,0,-1.52,0,root,12);cyl(70,70,.1,0xe4ead8,0,-1.8,0,root,64);path([[0,10],[0,7],[-.5,5],[-1,3]],1.4,0xdcca9f);const pad=cyl(4.3,4.3,.04,c.id==='verga'?0x9fa77a:0xb5c28c,-1,.02,1,root,32);gate=group(0,0,8.5);for(const x of [-1.5,1.5])box(.2,2,.2,0xa58860,x,1,0,gate);box(3.6,.55,.2,0xb69a6e,0,2.1,0,gate);const tx=textSprite('WELCOME CAMP','#fff9df',.38,gate);tx.position.set(0,2.12,.15);sign('CAMP SITE  ←',-2.4,5);for(let i=0;i<28;i++){let a=i/28*Math.PI*2;let x=Math.cos(a)*9,z=Math.sin(a)*8;if(z>5&&Math.abs(x)<3)continue;tree(x,z,.75+(i%4)*.18,['fuji','play','meadow','farm'].includes(c.land)?1:i%3===0?1:0)}if(c.id==='fumoto'){fuji(0,-9,1.15);for(let i=0;i<9;i++)tree(-13+i*3,-10,.7,0);}if(c.land==='cabins'){cabin(-6,-3,1.25);cabin(5,-5,1.1);playset(6,1);pondShape([[3,-1],[5,-2],[6,-1],[6,0],[4,1],[3,0]],0x9dcac6);fuji(1,-10,.9)}if(c.id==='verga'){pondShape([[-8,-8],[-6,-7],[-7,-4],[-6,0],[-7,4],[-6,8],[-8,9],[-9,4],[-8,0],[-9,-4]],0x94c5bf);for(let i=0;i<13;i++)rock(-6.5+Math.sin(i)*.6,-7+i*1.2,.3);cabin(5,-4,1);for(let i=0;i<10;i++)tree(-7+i*1.5,-8,1.3)}if(c.id==='mochiya'){fuji(2,-9,1.1);playset(-6,-2,1.4);playset(6,0,.85);const slide=box(1,.15,2.4,0xd6a16a,-4,1,-4);slide.rotation.x=.5;box(1,1.5,1,0xb9a075,-4,.75,-5);}for(let i=0;i<35;i++)flower(-4+(i%8)*.65,-1+Math.floor(i/8)*.5);addLandscape(c);tentGroup=shelter(-2,0,1.55,root,activeVisit.tentType||'dome');tentGroup.rotation.y=.18;fireGroup=makeFire();mealGroup=makeMeal();character=makeBear();moveTarget.copy(character.position);sleepText=textSprite('z Z z','#ecedc9',.65);sleepText.position.set(-2,2.6,0);sleepText.visible=false;const sg=new THREE.BufferGeometry();let pos=[];for(let i=0;i<250;i++)pos.push((Math.random()-.5)*100,12+Math.random()*40,-15-Math.random()*40);sg.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));stars=new THREE.Points(sg,new THREE.PointsMaterial({color:0xfff5cd,size:.12}));root.add(stars);stars.visible=false;cloud(-10,13,-12,2);cloud(10,11,-10,1.7);yaw=.4;pitch=.68;dist=34;wantedDist=34;camTarget.set(-.6,0,1);if(innerWidth<600){dist=37;wantedDist=37;camTarget.set(0,0,1.7)}updateScene();}
function addLandscape(c){if(['highland','mountain'].includes(c.land)){for(let i=0;i<5;i++)cone(2.6,3+i%3,0x8b9e7f,-8+i*4,1.4,-9,root,7);if(c.land==='mountain')for(let i=0;i<5;i++){const g=tree(-6+i*3,-5,1,1);g.children[0].material=material(0xdadbc3)}}if(['genshi','river'].includes(c.land)&&c.id!=='verga'){pondShape([[-8,-8],[-6,-8],[-6,0],[-7,4],[-6,8],[-8,9],[-9,3],[-8,-2]],0x94c5bf);for(let i=0;i<12;i++)rock(-6.6+Math.sin(i)*.5,-7+i*1.2,.3)}if(c.land==='genshi'){for(const [x,z] of [[-5,-5],[4,-4]]){const hut=group(x,0,z);const roof=tent(0,0,1.6,hut,0xb89b65);box(1.5,.5,1.6,0xa88f64,0,.25,0,hut);rod([-.7,2.2,0],[.7,2.5,0],.07,0x807054,hut)}}if(['lakefuji','highlake'].includes(c.land)){pondShape([[-9,-7],[-4,-8],[1,-7],[5,-8],[8,-5],[7,-2],[1,-3],[-4,-2],[-9,-4]],0x9ccac7);if(c.land==='lakefuji')fuji(1,-10,1);else for(let i=0;i<4;i++)cone(3,3+i%2,0x8a9e7f,-7+i*4,1.5,-10,root,7)}if(c.land==='forest'){cabin(-5,-4,1.3);cabin(5,-5,1);cone(5,4,0x8b9987,0,2,-10,root,9);for(let i=0;i<8;i++)tree(-7+i*2,-7,1.25)}if(c.land==='sea'){pondShape([[-12,-8],[12,-8],[12,-1],[-12,-2]],0x97c6cb);for(let i=0;i<4;i++)box(4,.025,.08,0xd4e6d9,-6+i*4,.07,-4-i%2);const g=group(6,0,-4);cyl(.1,.15,4.5,0xe4e0c8,0,2.25,0,g);for(let i=0;i<3;i++){const blade=box(.16,1.8,.08,0xf1e9d2,Math.sin(i*2.094)*.75,4+Math.cos(i*2.094)*.75,0,g);blade.rotation.z=-i*2.094}}if(['farm','meadow'].includes(c.land)){for(let i=0;i<8;i++){box(.12,.8,.12,0xcbb48b,-7+i*2,.4,-5);if(i<7)box(2,.09,.1,0xcbb48b,-6+i*2,.55,-5)}for(let i=0;i<5;i++){const hill=ball(3,0x9caf7d,-8+i*4,-.3,-10,root,8);hill.scale.y=.4}if(c.land==='farm'){const barn=cabin(5,-5,1.3);for(let i=0;i<3;i++){const g=group(-5+i*1.5,0,-4);const body=ball(.43,0xf0e9d8,0,.5,0,g);body.scale.set(1.4,.85,.8);ball(.22,0x777764,.5,.6,0,g);for(const x of [-.3,.3])rod([x,0,-.2],[x,.4,-.2],.04,0x807b65,g)}}}}
function enterCamp(){if(busy)return;const c=camps[selected];const pending=saved._active;activeVisit=pending?.campId===c.id?saved[c.id].visits.find(v=>v.id===pending.visitId&&!v.closed):null;if(!activeVisit){if(pending){const old=saved[pending.campId]?.visits.find(v=>v.id===pending.visitId);if(old)old.closed=true}activeVisit={id:globalThis.crypto?.randomUUID?.()||('visit-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)),startedAt:new Date().toISOString(),actions:{},tentType:null,closed:false};saved[c.id].visits.push(activeVisit);saved._active={campId:c.id,visitId:activeVisit.id}}save();mode='game';$('#sceneTag').textContent='⌖ キャンプ場の入口';$('#mapUI').hidden=true;$('#gameUI').hidden=false;$('#mapNav').classList.remove('active');$('#mapPins').innerHTML='';$('#locationRegion').textContent=c.region+' / '+c.en;$('#locationName').textContent=c.name;$('#locationDesc').textContent=c.desc;makeCamp();renderTasks();toast(`${c.short}へようこそ。今日は自由にそとあそび！`)}

function setNight(value){night=value;document.body.classList.toggle('night',value);scene.background.set(value?0x576e76:0xe7eddb);scene.fog.color.copy(scene.background);ambient.intensity=value?1.1:2.5;sun.intensity=value?.7:3.5;if(stars)stars.visible=value;clouds.forEach(c=>c.visible=!value);if(soundOn)updateAudio()}
function updateScene(){const s=activeVisit.actions;tentGroup.visible=!!s.tent;fireGroup.visible=!!s.fire;mealGroup.visible=!!s.meal;sleepText.visible=false;setNight(false);character.rotation.z=0;}
function renderTasks(){const c=camps[selected],n=actions.filter(a=>activeVisit.actions[a[0]]).length,s=activeVisit.actions;$('#taskCount').textContent=n?'✓ クリア':'自由に体験';$('#visitLabel').textContent=`今回：${visits(c).length+(n?0:1)}回目のキャンプ`;$('#tasks').innerHTML=actions.map(a=>`<div class="task ${s[a[0]]?'done':''}"><i>${s[a[0]]?'✓':a[1]}</i>${a[0]==='tent'&&s.tent?shelterTypes[activeVisit.tentType]+'で設営':a[2]}<small>${s[a[0]]?'できた！':'自由に選択'}</small></div>`).join('');$('#progressBar').style.width=n?'100%':'0%';$('#journalNote').textContent=n?'この訪問はクリア！ 続けて遊んでも、次の場所へ行ってもOK。':'どれか1つ楽しむだけでクリア。テントなしの焚き火やお昼寝もOK！';$('#actionDock').innerHTML=actions.map(a=>`<button class="action ${s[a[0]]?'done':''}" data-action="${a[0]}" ${busy?'disabled':''}><span class="icon">${a[1]}</span><strong>${a[2]}</strong><small>${s[a[0]]?(a[0]==='tent'?'種類を変える':'もう一度楽しむ'):a[3]}</small></button>`).join('');document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>b.dataset.action==='tent'?chooseShelter():doAction(b.dataset.action));$('#navCount').textContent=camps.filter(c=>count(c)>0).length+'/'+camps.length;$('#finishVisit').textContent=n?'✓ キャンプを終えて地図へ':'体験せず地図へもどる';}
let animAction=null;
async function doAction(id,tentType){if(busy||!activeVisit)return;const wasClear=actions.some(a=>activeVisit.actions[a[0]]);busy=true;if(night){setNight(false);sleepText.visible=false;character.rotation.z=0;character.position.y=0}if(id==='tent'){activeVisit.tentType=tentType||'dome';root.remove(tentGroup);tentGroup=shelter(-2,0,1.55,root,activeVisit.tentType);tentGroup.visible=false}renderTasks();const dest={tent:[-1,0,2.5],fire:[1,0,2.5],meal:[-1.4,0,3.45],sleep:[-2,0,.4]}[id];moveTarget.set(...dest);$('#sceneTag').textContent={tent:'⛺ 自分だけの基地を準備中…',fire:'🔥 薪を組んで、火を灯そう…',meal:'🍳 あつあつのごはん、できあがり。',sleep:'🌙 おやすみの準備…'}[id];animAction={id,start:clock.getElapsedTime()};await new Promise(r=>setTimeout(r,1800));activeVisit.actions[id]=true;character.position.set(...dest);moveTarget.copy(character.position);save();if(id==='tent')tentGroup.visible=true;if(id==='fire'){fireGroup.visible=true;setNight(false)}if(id==='meal')mealGroup.visible=true;if(id==='sleep'){setNight(true);fireGroup.visible=false;sleepText.visible=true;character.position.set(-2,.12,.4);character.rotation.z=Math.PI/2;moveTarget.copy(character.position)}busy=false;renderTasks();$('#sceneTag').textContent={tent:`⛺ ${shelterTypes[activeVisit.tentType]}の基地ができました`,fire:'🔥 ぱちぱち。あたたかいね',meal:'🍳 おそとで食べると、おいしいね',sleep:'🌙 コモは夢の中。おやすみなさい'}[id];toast(wasClear?'✓ 思い出を記録しました。':`✦ キャンプ場クリア！ ${camps[selected].short}・${visits(camps[selected]).length}回目の思い出`)}
function closeVisit(){if(activeVisit){activeVisit.closed=true;if(!actions.some(a=>activeVisit.actions[a[0]]))saved[camps[selected].id].visits=saved[camps[selected].id].visits.filter(v=>v!==activeVisit);delete saved._active;activeVisit=null;save()}}
function goMap(){if(busy){toast('もう少しでできあがります。');return}closeVisit();mode='map';$('#mapUI').hidden=false;$('#gameUI').hidden=true;$('#mapNav').classList.add('active');makeMap();if(soundOn)updateAudio()}

function showModal(html,wide=false){$('#modal').classList.toggle('wide',wide);$('#modalContent').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function showRecords(){showModal(`<div class="eyebrow">CAMPING PASSPORT</div><h2>旅と、そとあそびの記録。</h2><p>${camps.filter(c=>count(c)>0).length} / ${camps.length} か所クリア ・ 合計 ${camps.reduce((n,c)=>n+visits(c).length,0)} 回のキャンプ<br>1つでも体験した訪問を1回と数えます。各体験の数字は、その体験をした訪問の数です。</p><div class="tableScroll"><table class="recordsTable"><thead><tr><th>キャンプ場</th><th>訪問</th>${actions.map(a=>`<th>${a[1]}<small>${a[0]==='tent'?'設営':a[2].replace('をする','').replace('をたべる','')}</small></th>`).join('')}<th>訪問ごと</th></tr></thead><tbody>${camps.map((c,i)=>`<tr><td><strong>${count(c)?'✓ ':''}${c.short}</strong><small>${c.region}</small></td><td><b>${visits(c).length}</b> 回</td>${actions.map(a=>`<td class="${did(c,a[0])?'achieved':'notyet'}">${did(c,a[0])?'✓ '+visits(c).filter(v=>v.actions[a[0]]).length:'—'}</td>`).join('')}<td><button class="historyBtn" data-history="${i}">履歴 →</button></td></tr>`).join('')}</tbody></table></div><p class="fineprint">${saveFailed?'このブラウザでは保存できません。':'この端末・ブラウザに自動保存。以前の体験記録も引き継いでいます。'} ゲーム内の訪問記録です。</p>`,true);document.querySelectorAll('[data-history]').forEach(b=>b.onclick=()=>showHistory(+b.dataset.history))}
function showHistory(i){const c=camps[i],list=visits(c);showModal(`<button class="textBack" id="recordsBack">← すべての記録へ</button><div class="eyebrow">${c.pref} / VISIT HISTORY</div><h2>${c.name}</h2><p>${list.length}回のキャンプ ・ 体験したこと ${count(c)}種類</p><div class="visitHistory">${list.length?list.map((v,j)=>`<article class="visitCard"><div><b>${j+1}回目</b><time>${dateLabel(v.startedAt)}</time>${!v.closed?'<span class="ongoing">滞在中</span>':''}</div><div class="historyActivities">${actions.map(a=>`<span class="${v.actions[a[0]]?'earned':'notyet'}">${a[1]} ${v.actions[a[0]]?(a[0]==='tent'?shelterTypes[v.tentType]||'ロッジ型':a[2]):'未体験'}</span>`).join('')}</div>${v.legacy?'<small>更新前の体験をまとめた記録です。当時の訪問回数は復元できないため1回として引き継ぎました。</small>':''}</article>`).join(''):'<p>まだ体験の記録がありません。好きなことを1つ、楽しみに行こう。</p>'}</div>`,true);$('#recordsBack').onclick=showRecords}
$('#backBtn').onclick=goMap;$('#finishVisit').onclick=goMap;$('#mapNav').onclick=goMap;$('.brand').onclick=e=>{e.preventDefault();goMap()};$('#bookNav').onclick=showRecords;$('.close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
$('#helpBtn').onclick=()=>showModal(`<div class="eyebrow">HOW TO PLAY</div><h2>今日は、好きなことだけ。</h2><p>1. 地図や県別一覧からキャンプ場を選んで入口へ。<br>2. テント・焚き火・ごはん・ねるを、好きな順で自由に体験。<br>3. どれか1つできたら、そのキャンプ場はクリア！<br>4. 地図へ戻って再訪すると、2回目・3回目の旅に。</p><p>テント・宿泊場所はドーム型、ワンポール型、ロッジ型、コテージから選べます。設営せずに焚き火や食事、お昼寝だけ楽しんでもOK。</p><p>地図には、これまで体験した道具だけが小さく登場。設営していない場所にはテントを表示しません。「キャンプの記録」で全体の体験一覧と訪問ごとの履歴を確認できます。</p><p>体験をした滞在を1回と数えます。同じ滞在中に何度体験しても訪問は1回。再読み込み後も、地図から同じキャンプ場へ戻ると滞在を再開できます。</p><p>ドラッグで視点回転、スクロールで拡大・縮小。地面をクリック、または矢印キー・WASDで歩けます。♪ で環境音を切り替え。記録はこのブラウザに自動保存します。</p>`);
$('#aboutBtn').onclick=()=>showModal(`<div class="eyebrow">ABOUT THIS LITTLE WORLD</div><h2>本物の自然から、<br>小さな世界へ。</h2><p>関東・甲信越・静岡の21キャンプ場をモチーフにした非公式の3Dゲームです。地図の海岸線にはNatural Earthの公開地理データを使用しています。キャンプ場の位置は地域を表す概略で、見やすさのためにずらした目印もあります。地形・施設配置・距離はゲーム向けにデフォルメしています。宿泊タイプはゲーム内の自由な演出で、現地の宿泊施設や利用可否とは異なります。</p><p>各地の公式施設案内を参考に、森と清流、湖と山、高原、牧場、海風の雰囲気を表現しました。</p><p>参考にした公式サイト</p><ul>${camps.map(c=>`<li><a href="${c.url}" target="_blank" rel="noopener">${c.name} ↗</a></li>`).join('')}</ul><p class="fineprint">現地への訪問・予約・宿泊施設の確認には、各キャンプ場の公式情報をご利用ください。</p>`);
$('#rotateLeft').onclick=()=>yaw-=.4;$('#rotateRight').onclick=()=>yaw+=.4;$('#homeView').onclick=()=>{yaw=.48;pitch=.58;wantedDist=innerWidth<600?37:31;camTarget.set(-.6,0,1)};
const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2(),groundPlane=new THREE.Plane(new THREE.Vector3(0,1,0),0);const canvas=renderer.domElement;canvas.addEventListener('pointerdown',e=>{dragging=true;moved=false;last={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!dragging)return;let dx=e.clientX-last.x,dy=e.clientY-last.y;if(Math.abs(dx)+Math.abs(dy)>2)moved=true;yaw-=dx*.006;pitch=Math.max(.32,Math.min(1.12,pitch+dy*.004));last={x:e.clientX,y:e.clientY}});canvas.addEventListener('pointerup',e=>{dragging=false;if(!moved&&mode==='game'&&!busy&&!night){pointer.set(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1);raycaster.setFromCamera(pointer,camera);let p=new THREE.Vector3();if(raycaster.ray.intersectPlane(groundPlane,p)&&Math.hypot(p.x,p.z)<10){moveTarget.set(p.x,0,p.z);$('#sceneTag').textContent='⌖ コモと、おさんぽ'}}});canvas.addEventListener('pointercancel',()=>dragging=false);canvas.addEventListener('wheel',e=>{e.preventDefault();wantedDist=Math.max(20,Math.min(mode==='map'?400:80,wantedDist+e.deltaY*.025))},{passive:false});const keys={};window.addEventListener('keydown',e=>{if($('#modal').open)return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','w','a','s','d'].includes(e.key)){e.preventDefault();keys[e.key]=true}});window.addEventListener('keyup',e=>keys[e.key]=false);window.addEventListener('blur',()=>Object.keys(keys).forEach(k=>keys[k]=false));
let audioCtx,noiseSource,noiseGain,filter;
function updateAudio(){if(!audioCtx)return;noiseGain.gain.setTargetAtTime(soundOn?(night?.025:.045):0,audioCtx.currentTime,.4);filter.frequency.setTargetAtTime(night?600:1300,audioCtx.currentTime,.4)}
$('#soundBtn').onclick=async()=>{try{if(!audioCtx){audioCtx=new AudioContext();const b=audioCtx.createBuffer(1,audioCtx.sampleRate*4,audioCtx.sampleRate);const d=b.getChannelData(0);let last=0;for(let i=0;i<d.length;i++){last=(last+Math.random()*.04-.02)/1.02;d[i]=last*8}noiseSource=audioCtx.createBufferSource();noiseSource.buffer=b;noiseSource.loop=true;filter=audioCtx.createBiquadFilter();filter.type='lowpass';noiseGain=audioCtx.createGain();noiseGain.gain.value=0;noiseSource.connect(filter);filter.connect(noiseGain);noiseGain.connect(audioCtx.destination);noiseSource.start()}await audioCtx.resume();soundOn=!soundOn;updateAudio();$('#soundBtn').textContent=soundOn?'♪ ON':'♪ OFF';toast(soundOn?'風と木々の音に、耳をすませて。':'環境音をオフにしました。')}catch{toast('このブラウザでは環境音を再生できません。')}};
function updateListScroll(){const list=$('#campList'),rail=$('#listRail'),thumb=$('#listThumb'),max=list.scrollHeight-list.clientHeight;const needs=max>2;rail.hidden=!needs;const h=Math.max(32,rail.clientHeight*(list.clientHeight/Math.max(1,list.scrollHeight)));thumb.style.height=h+'px';thumb.style.top=(max>0?(rail.clientHeight-h)*list.scrollTop/max:0)+'px';thumb.setAttribute('aria-valuemax',String(Math.max(0,Math.round(max))));thumb.setAttribute('aria-valuenow',String(Math.round(list.scrollTop)));$('#scrollNext').disabled=!needs||list.scrollTop>=max-2;$('#listPosition').textContent=needs?'SCROLL TO EXPLORE':'すべて表示中';$('.campListFrame').classList.toggle('atBottom',!needs||list.scrollTop>=max-2)}
$('#campList').addEventListener('scroll',updateListScroll,{passive:true});$('#scrollNext').onclick=()=>$('#campList').scrollBy({top:190,behavior:'smooth'});let scrollDrag=null;$('#listThumb').addEventListener('pointerdown',e=>{e.preventDefault();scrollDrag={y:e.clientY,top:$('#campList').scrollTop};$('#listThumb').setPointerCapture(e.pointerId)});$('#listThumb').addEventListener('pointermove',e=>{if(!scrollDrag)return;const list=$('#campList'),travel=$('#listRail').clientHeight-$('#listThumb').clientHeight;list.scrollTop=scrollDrag.top+(e.clientY-scrollDrag.y)*(list.scrollHeight-list.clientHeight)/Math.max(1,travel)});for(const event of ['pointerup','pointercancel'])$('#listThumb').addEventListener(event,()=>scrollDrag=null);$('#listThumb').addEventListener('keydown',e=>{if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const list=$('#campList');if(e.key==='Home')list.scrollTop=0;else if(e.key==='End')list.scrollTop=list.scrollHeight;else list.scrollBy({top:e.key==='ArrowDown'?90:-90,behavior:'smooth'})}});
$('#japanView').onclick=()=>setMapView(true);$('#areaView').onclick=()=>setMapView(false);
function resize(){lastPinLayout=0;requestAnimationFrame(updateListScroll);renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix()}addEventListener('resize',resize);
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.15),t=clock.elapsedTime;dist+=(wantedDist-dist)*.08;const cp=new THREE.Vector3(camTarget.x+Math.sin(yaw)*Math.cos(pitch)*dist,camTarget.y+Math.sin(pitch)*dist,camTarget.z+Math.cos(yaw)*Math.cos(pitch)*dist);camera.position.lerp(cp,.09);camera.lookAt(camTarget);clouds.forEach((c,i)=>{c.position.x+=Math.sin(t*.1+i)*dt*.025});if(mode==='map'){layoutPins()}else if(character){if(!busy&&!night&&!$('#modal').open){let dx=(keys.d||keys.ArrowRight?1:0)-(keys.a||keys.ArrowLeft?1:0),dz=(keys.s||keys.ArrowDown?1:0)-(keys.w||keys.ArrowUp?1:0);if(dx||dz){const nx=character.position.x+dx*dt*4,nz=character.position.z+dz*dt*4;if(Math.hypot(nx,nz)<10)moveTarget.set(nx,0,nz)}}if(!night){const delta=moveTarget.clone().sub(character.position);delta.y=0;const len=delta.length();if(len>.04){const step=Math.min(len,dt*3);character.position.add(delta.normalize().multiplyScalar(step));character.rotation.y=Math.atan2(delta.x,delta.z);character.position.y=Math.sin(t*13)*.045}else character.position.y=Math.sin(t*2)*.025}if(tentGroup.visible&&tentGroup.scale.x<1.55){const a=Math.min(1.55,tentGroup.scale.x+dt*2);tentGroup.scale.setScalar(a)}flames.forEach((f,i)=>{f.scale.y=.7+Math.sin(t*9+i*2)*.25;f.rotation.y=t+i});if(sleepText.visible){sleepText.position.y=2.7+Math.sin(t*1.5)*.2;character.scale.y=1.25+Math.sin(t*2)*.025}else character.scale.y=1.25;if(animAction&&t-animAction.start<2&&character)character.rotation.y+=Math.sin(t*12)*.03;}renderer.render(scene,camera)}
save();makeMap();camera.position.set(0,46,41);animate();
